import csv
def dump(f, n=50):
    print("==", f)
    try:
        rows = list(csv.reader(open(f)))
    except Exception as e:
        print("ERR", e); return
    print("nrows:", len(rows))
    for r in rows[:n]:
        print(r)
dump("ae_ip_termination.csv", 40)
dump("ae_ip_termination_by_month.csv", 60)
